factorial.body:
{
    if n > MAX_FACTORIAL_ARGUMENT {
        return Err(CombinatoricsError::ArgumentTooLarge {
            what: "factorial",
            argument: u64::try_from(n).unwrap_or(u64::MAX),
            max: u64::try_from(MAX_FACTORIAL_ARGUMENT).unwrap_or(u64::MAX),
        });
    }
    let mut product = BigUint::one();
    for i in 2..=n {
        product *= BigUint::from(i);
    }
    Ok(product)
}

binomial.body:
{
    if k > n {
        return Ok(BigUint::zero());
    }
    let m = k.min(n - k);
    if m > MAX_BINOMIAL_CHOICE {
        return Err(CombinatoricsError::ArgumentTooLarge {
            what: "binomial",
            argument: m,
            max: MAX_BINOMIAL_CHOICE,
        });
    }
    let mut result = BigUint::one();
    for i in 1..=m {
        result *= BigUint::from(n - m + i);
        result /= BigUint::from(i);
    }
    Ok(result)
}

budget.body:
{
    if *requested > BigUint::from(limit) {
        Err(CombinatoricsError::BudgetExceeded {
            what,
            requested: requested.clone(),
            limit,
        })
    } else {
        Ok(())
    }
}

next_permutation.body:
{
    let n = items.len();
    if n < 2 {
        return false;
    }
    let mut i = n - 1;
    while i > 0 && items[i - 1] >= items[i] {
        i -= 1;
    }
    if i == 0 {
        return false;
    }
    let mut j = n - 1;
    while items[j] <= items[i - 1] {
        j -= 1;
    }
    items.swap(i - 1, j);
    items[i..].reverse();
    true
}

next_combination.body:
{
    let k = combination.len();
    if k > n || combination.iter().any(|&c| c >= n) || combination.windows(2).any(|w| w[0] >= w[1])
    {
        return false;
    }
    let mut i = k;
    while i > 0 {
        i -= 1;
        if combination[i] < n - k + i {
            combination[i] += 1;
            for j in (i + 1)..k {
                combination[j] = combination[j - 1] + 1;
            }
            return true;
        }
    }
    false
}

weak_compositions.body:
{
    admit_width("weak composition parts", parts)?;
    let count = if parts == 0 {
        if total == 0 {
            BigUint::one()
        } else {
            BigUint::zero()
        }
    } else {
        let upper = total
            .checked_add(parts - 1)
            .and_then(|s| u64::try_from(s).ok())
            .ok_or(CombinatoricsError::ArgumentTooLarge {
                what: "weak_compositions",
                argument: u64::MAX,
                max: u64::MAX - 1,
            })?;
        binomial(upper, u64::try_from(parts - 1).unwrap_or(u64::MAX))?
    };
    budget("weak compositions", &count, limit)?;
    budget(
        "weak composition cells",
        &(count * BigUint::from(parts)),
        MAX_COMPOSITION_CELLS,
    )?;
    Ok(collect_compositions(total, parts))
}

admit_width.body:
{
    if width > MAX_ENUMERATION_WIDTH {
        return Err(CombinatoricsError::ArgumentTooLarge {
            what,
            argument: u64::try_from(width).unwrap_or(u64::MAX),
            max: MAX_ENUMERATION_WIDTH as u64,
        });
    }
    Ok(())
}

collect_compositions.body:
{
    if parts == 0 {
        return if total == 0 { vec![vec![]] } else { vec![] };
    }
    let mut out = Vec::new();
    let mut current = vec![0; parts];
    current[parts - 1] = total;
    loop {
        out.push(current.clone());
        if !next_composition(&mut current) {
            return out;
        }
    }
}

next_composition.body:
{
    let Some(pivot) = current[1..].iter().rposition(|&value| value != 0) else {
        return false;
    };
    let index = pivot + 1;
    let remaining = current[index] - 1;
    current[index] = 0;
    current[index - 1] += 1;
    let last = current.len() - 1;
    current[last] = remaining;
    true
}

